package main

// The /mcp game tools against pflow-native. parity/native/game_goldens.json is
// native's answer to each call in parity/native/game_cases.json (generated by
// parity/native/gen-game, `make game-goldens`): game.value and game.move on
// positions of tic-tac-toe, Connect-3, Connect-4, Nim and prize games, under
// every plan piece the Go search ports, and the refusals. This replays every
// case through the tool's own handler and compares, exactly: the value, the
// move, the node count (which counts the table's every eviction), the budget
// and the words of an error.
//
// A case whose plan names the root estimate "ode" is the one kind native
// answers and the tool must refuse (`ported: false` in the golden): the test
// holds the tool to refusing it, and saying why.
//
// Two normalisations, on error text: the position serde_json gives a parse
// error (" at line 1 column 7") is dropped from both sides, and the tool's
// tighter caps (mcp_game.go) are worded as native's in its messages.

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"regexp"
	"strings"
	"testing"
)

type gameGolden struct {
	Name    string         `json:"name"`
	Fixture string         `json:"fixture"`
	Marking map[string]int `json:"marking"`
	Tool    string         `json:"tool"`
	Args    map[string]any `json:"args"`
	Expect  map[string]any `json:"expect"`
	Error   *string        `json:"error"`
	Ported  *bool          `json:"ported"`
}

func loadGameGoldens(t *testing.T) []gameGolden {
	t.Helper()
	var golden struct {
		PflowNative string       `json:"pflow_native"`
		PflowRS     string       `json:"pflow_rs"`
		Cases       []gameGolden `json:"cases"`
	}
	loadJSON(t, "../../parity/native/game_goldens.json", &golden)
	if golden.PflowNative == "" || golden.PflowRS == "" || len(golden.Cases) == 0 {
		t.Fatal("game_goldens.json names no pflow-native and pflow-rs commits, or has no cases")
	}
	return golden.Cases
}

// gameNet is the case's fixture with its marking set to the position.
func gameNet(t *testing.T, c gameGolden) map[string]any {
	t.Helper()
	var doc map[string]any
	loadJSON(t, "../../parity/"+c.Fixture, &doc)
	places, _ := doc["places"].(map[string]any)
	for id := range c.Marking {
		if _, ok := places[id]; !ok {
			t.Fatalf("%s: marking names %s, which %s does not have", c.Name, id, c.Fixture)
		}
	}
	for id, p := range places {
		p.(map[string]any)["initial"] = []any{float64(c.Marking[id])}
	}
	return doc
}

var serdePosition = regexp.MustCompile(` at line \d+ column \d+`)

// serverCaps words the tool's tighter caps (mcp_game.go) as native's.
var serverCaps = strings.NewReplacer("1..10000000", "1..100000000", "at most 10000000", "at most 100000000", "at most 2097152", "at most 8388608")

func normalizeGameError(s string) string { return serdePosition.ReplaceAllString(s, "") }

var gameHandlers = map[string]func(*Server, *http.Request, map[string]any) (any, error){
	"game.value": mcpGameValue, "game.move": mcpGameMove,
}

// runGame replays one golden case through the tool's handler.
func runGameCase(t *testing.T, c gameGolden) (any, error) {
	t.Helper()
	run, ok := gameHandlers[c.Tool]
	if !ok {
		t.Fatalf("no handler for %s", c.Tool)
	}
	args := map[string]any{"net": gameNet(t, c)}
	for k, v := range c.Args {
		args[k] = v
	}
	return run(&Server{}, httptest.NewRequest("POST", "/mcp", nil), args)
}

func TestMCPGameMatchesNative(t *testing.T) {
	seen := map[string]int{}
	refused := 0
	for _, c := range loadGameGoldens(t) {
		t.Run(c.Name, func(t *testing.T) {
			out, err := runGameCase(t, c)
			if c.Ported != nil && !*c.Ported {
				// Native solves the ODE; the tool refuses, and says what.
				if err == nil {
					t.Fatalf("native answered with the ode estimate (%v); the tool answered too: %v", c.Expect, out)
				}
				if !strings.Contains(err.Error(), `"ode"`) || !strings.Contains(err.Error(), "not ported") {
					t.Fatalf("the refusal does not say that the ode estimate is not ported: %v", err)
				}
				refused++
				return
			}
			if c.Error != nil {
				if err == nil {
					t.Fatalf("native refused (%s); the tool answered: %v", *c.Error, out)
				}
				if got, want := serverCaps.Replace(normalizeGameError(err.Error())), normalizeGameError(*c.Error); got != want {
					t.Fatalf("error differs:\n tool:   %s\n native: %s", got, want)
				}
				seen["error"]++
				return
			}
			if err != nil {
				t.Fatalf("tool error: %v", err)
			}
			b, _ := json.Marshal(out)
			var act any
			if err := json.Unmarshal(b, &act); err != nil {
				t.Fatal(err)
			}
			if d := jsonDiff(c.Expect, act, "", constTolerance(0), nil); len(d) > 0 {
				t.Fatalf("differs from native:\n%s", strings.Join(d, "\n"))
			}
			seen[c.Tool]++
		})
	}
	for _, tool := range []string{"game.value", "game.move", "error"} {
		if seen[tool] == 0 {
			t.Errorf("no golden case for %s", tool)
		}
	}
	if refused == 0 {
		t.Error("no golden case for the refused ode estimate")
	}
}
